package com.example.transactionrecovery.service;
import com.example.transactionrecovery.domain.*; import com.example.transactionrecovery.repository.*; import com.fasterxml.jackson.databind.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*; import static com.example.transactionrecovery.domain.States.*;
@Service public class SagaConsumer {static final String CONSUMER="service-saga";private final SagaRepository sagas;private final ApplicationRepository apps;private final ProcessedEventRepository processed;private final ObjectMapper json;public SagaConsumer(SagaRepository s,ApplicationRepository a,ProcessedEventRepository p,ObjectMapper j){sagas=s;apps=a;processed=p;json=j;}
 @Transactional public boolean consume(OutboxEvent event){if(processed.existsByConsumerNameAndEventId(CONSUMER,event.id))return false;try{JsonNode p=json.readTree(event.payload);UUID sagaId=UUID.fromString(p.get("sagaId").asText()),appId=UUID.fromString(p.get("applicationId").asText());Saga saga=sagas.findById(sagaId).orElseThrow();ServiceApplication app=apps.findById(appId).orElseThrow();saga.transition(SagaStatus.RESOURCE_ALLOCATED);saga.transition(SagaStatus.ACTIVATING);if(!app.activationShouldFail){app.status=ApplicationStatus.ACTIVE;saga.transition(SagaStatus.COMPLETED);}else{compensate(saga,app);}processed.saveAndFlush(new ProcessedEvent(CONSUMER,event.id,event.tenantId));return true;}catch(RuntimeException e){throw e;}catch(Exception e){throw new IllegalArgumentException("Invalid event",e);}}
 private void compensate(Saga saga,ServiceApplication app){saga.transition(SagaStatus.COMPENSATING);for(int attempt=1;attempt<=3;attempt++){saga.compensationAttempts++;if(app.compensationFailuresRemaining>0){app.compensationFailuresRemaining--;continue;}app.status=ApplicationStatus.CANCELLED;saga.transition(SagaStatus.COMPENSATED);return;}saga.transition(SagaStatus.MANUAL_REQUIRED);}
}
